contracts/core/BiddingEscrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import {Ownable} from '@openzeppelin/contracts/access/Ownable.sol';
import {Address} from '@openzeppelin/contracts/utils/Address.sol';

/**
 * @title Bidding Escrow
 * @notice Holds user funds used by CacheManagerAutomation for cache bids and
 * program activations.
 * @dev The deploying CacheManagerAutomation contract owns this contract and
 * exclusively manages deposits, user withdrawals, and transfers needed for
 * protocol operations.
 */
contract BiddingEscrow is Ownable {
    using Address for address payable;

    error AmountExceedsBalance();

    event Deposited(address indexed payee, uint256 weiAmount);
    event Withdrawn(address indexed payee, uint256 weiAmount);
    event WithdrawnForAutomation(
        address indexed depositor,
        address indexed recipient,
        uint256 weiAmount
    );

    mapping(address account => uint256 balance) private _deposits;

    function depositsOf(address payee) public view returns (uint256) {
        return _deposits[payee];
    }

    /**
     * @dev Stores the sent amount as credit to be withdrawn.
     * @param payee The destination address of the funds.
     *
     * Emits a {Deposited} event.
     */
    function deposit(address payee) public payable virtual onlyOwner {
        uint256 amount = msg.value;
        _deposits[payee] += amount;
        emit Deposited(payee, amount);
    }

    /**
     * @dev Withdraw accumulated balance for a payee, forwarding all gas to the
     * recipient.
     *
     * WARNING: Forwarding all gas opens the door to reentrancy vulnerabilities.
     * Make sure you trust the recipient, or are either following the
     * checks-effects-interactions pattern or using {ReentrancyGuard}.
     *
     * @param payee The address whose funds will be withdrawn and transferred to.
     *
     * Emits a {Withdrawn} event.
     */
    function withdraw(address payable payee) public virtual onlyOwner {
        uint256 payment = _deposits[payee];

        _deposits[payee] = 0;

        payee.sendValue(payment);

        emit Withdrawn(payee, payment);
    }

    /**
     * @dev Withdraws a specific amount from a user's balance to the owner
     * contract for cache bids or program activations.
     *
     * WARNING: This function should only be called by the owner contract while
     * executing one of those operations.
     *
     * @param depositor The address whose funds will be partially withdrawn
     * @param amount The amount to withdraw for the protocol operation
     *
     * Emits a {WithdrawnForAutomation} event.
     */
    function withdrawForAutomation(
        address depositor,
        uint256 amount
    ) public onlyOwner {
        uint256 balance = _deposits[depositor];

        if (amount > balance) {
            revert AmountExceedsBalance();
        }

        _deposits[depositor] = balance - amount;

        address recipient = msg.sender;
        payable(recipient).sendValue(amount);

        emit WithdrawnForAutomation(depositor, recipient, amount);
    }
}

contracts/core/CacheManagerAutomation.so.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

// OpenZeppelin
import {EnumerableSet} from '@openzeppelin/contracts/utils/structs/EnumerableSet.sol';
import {Ownable2Step} from '@openzeppelin/contracts/access/Ownable2Step.sol';
import {ReentrancyGuard} from '@openzeppelin/contracts/security/ReentrancyGuard.sol';
import {ArbSys} from '@arbitrum/nitro-contracts/src/precompiles/ArbSys.sol';
import {BiddingEscrow} from './BiddingEscrow.sol';

// Interfaces
import '../interfaces/IExternalContracts.sol';
import '../interfaces/ICacheManagerAutomation.sol';

/// @title Cache Manager Automation
/// @notice A automation contract that manages user bids for contract caching in the Stylus VM
contract CacheManagerAutomation is
    ICacheManagerAutomation,
    Ownable2Step,
    ReentrancyGuard
{
    using EnumerableSet for EnumerableSet.AddressSet;
    BiddingEscrow public immutable escrow;

    /// @dev bytes4(keccak256("ProgramExpired(uint64)")).
    /// ArbWasm.programTimeLeft reverts with this custom error once a program
    /// has expired in recent Nitro versions. Treated as "proceed to activate".
    bytes4 private constant PROGRAM_EXPIRED_SELECTOR = 0xc9b12e52;
    /// @dev bytes4(keccak256("ProgramNeedsUpgrade(uint16,uint16)")); an old
    /// program version must be reactivated against the current Stylus version.
    bytes4 private constant PROGRAM_NEEDS_UPGRADE_SELECTOR = 0x637d968f;
    ArbSys private constant ARB_SYS = ArbSys(address(100));
    // Operational limits match the tested/default batch and pagination sizes.
    uint256 private constant MAX_BIDS_PER_ITERATION_LIMIT = 50;
    uint256 private constant MAX_CONTRACTS_PER_USER_LIMIT = 100;
    uint256 private constant MAX_USERS_PER_PAGE_LIMIT = 100;
    uint256 private constant MAX_HORIZON_SECONDS = 365 days;
    uint192 private constant MAX_BID_INCREMENT = 1 ether;

    // ------------------------------------------------------------------------
    // Configuration state variables (modifiable by owner)
    // ------------------------------------------------------------------------
    uint256 public maxContractsPerUser;
    uint256 public minMaxBidAmount;
    uint256 public minFundAmount;
    uint256 public maxUserFunds;
    uint256 public maxBidsPerIteration;
    uint256 public maxUsersPerPage;
    uint256 public cacheThreshold;
    uint256 public horizonSeconds;
    uint192 public bidIncrement;
    uint256 public maxActivationsPerIteration;

    // ------------------------------------------------------------------------
    // State variables
    // ------------------------------------------------------------------------

    ICacheManager public immutable cacheManager;
    IArbWasmCache public immutable arbWasmCache;
    IArbWasm public immutable arbWasm;
    mapping(address user => ContractConfig[] contracts) public userContracts;
    EnumerableSet.AddressSet private usersWithContracts;
    /// @dev Prevents one user's escrow from paying more than once per block to
    ///      cache the same codehash. Stylus cache entries are keyed by codehash,
    ///      so multiple contract addresses may refer to the same entry.
    mapping(address user => mapping(bytes32 codehash => uint256 blockNumber))
        private lastPaidBidBlock;

    // ------------------------------------------------------------------------
    // Constructor
    // ------------------------------------------------------------------------

    /// @notice Initializes the contract
    constructor(
        address _cacheManager,
        address _arbWasmCache,
        address _arbWasm
    ) {
        if (_cacheManager == address(0)) revert InvalidAddress();
        if (_arbWasmCache == address(0)) revert InvalidAddress();
        if (_arbWasm == address(0)) revert InvalidAddress();

        cacheManager = ICacheManager(_cacheManager);
        arbWasmCache = IArbWasmCache(_arbWasmCache);
        arbWasm = IArbWasm(_arbWasm);
        escrow = new BiddingEscrow();

        // Initialize configuration parameters with default values
        maxContractsPerUser = 50;
        minMaxBidAmount = 1;
        minFundAmount = 1;
        maxUserFunds = 1 ether;
        maxBidsPerIteration = 50;
        maxUsersPerPage = 100;
        cacheThreshold = 98; // Start bidding when 98% full (10mb free for 512mb cache)
        horizonSeconds = 30 days; // Target 30 days to become competitive
        bidIncrement = 1; // Bid increment for uniqueness
        // Activations are ~3.3M gas each; keep the default conservative so the
        // batch fits in any block. Owner can raise it via setter.
        maxActivationsPerIteration = 5;
    }

    // ------------------------------------------------------------------------
    // Emergency functions
    // ------------------------------------------------------------------------

    // ------------------------------------------------------------------------
    // Admin functions
    // ------------------------------------------------------------------------

    /// @notice Ownership renunciation is disabled to preserve administration.
    function renounceOwnership() public view override onlyOwner {
        revert OwnershipRenunciationDisabled();
    }

    /// @notice Set maximum contracts per user
    /// @param _maxContractsPerUser New maximum contracts per user
    function setMaxContractsPerUser(
        uint256 _maxContractsPerUser
    ) external onlyOwner {
        if (
            _maxContractsPerUser == 0 ||
            _maxContractsPerUser > MAX_CONTRACTS_PER_USER_LIMIT
        ) revert InvalidMaxContractsPerUser();
        uint256 oldValue = maxContractsPerUser;
        maxContractsPerUser = _maxContractsPerUser;
        emit MaxContractsPerUserUpdated(oldValue, _maxContractsPerUser);
    }

    /// @notice Set minimum maximum bid amount
    /// @param _minMaxBidAmount New minimum maximum bid amount
    function setMinMaxBidAmount(uint256 _minMaxBidAmount) external onlyOwner {
        if (_minMaxBidAmount == 0) revert InvalidMinMaxBidAmount();
        uint256 oldValue = minMaxBidAmount;
        minMaxBidAmount = _minMaxBidAmount;
        emit MinMaxBidAmountUpdated(oldValue, _minMaxBidAmount);
    }

    /// @notice Set minimum fund amount
    /// @param _minFundAmount New minimum fund amount
    function setMinFundAmount(uint256 _minFundAmount) external onlyOwner {
        if (_minFundAmount == 0 || _minFundAmount > maxUserFunds)
            revert InvalidMinFundAmount();
        uint256 oldValue = minFundAmount;
        minFundAmount = _minFundAmount;
        emit MinFundAmountUpdated(oldValue, _minFundAmount);
    }

    /// @notice Set maximum user funds
    /// @param _maxUserFunds New maximum user funds
    /// @dev Applied prospectively; existing balances above a lowered limit can
    ///      still be withdrawn but cannot be funded further.
    function setMaxUserFunds(uint256 _maxUserFunds) external onlyOwner {
        if (_maxUserFunds < minFundAmount) revert InvalidMaxUserFunds();
        uint256 oldValue = maxUserFunds;
        maxUserFunds = _maxUserFunds;
        emit MaxUserFundsUpdated(oldValue, _maxUserFunds);
    }

    /// @notice Set maximum bids per iteration
    /// @param _maxBidsPerIteration New maximum bids per iteration
    function setMaxBidsPerIteration(
        uint256 _maxBidsPerIteration
    ) external onlyOwner {
        if (
            _maxBidsPerIteration == 0 ||
            _maxBidsPerIteration > MAX_BIDS_PER_ITERATION_LIMIT
        ) revert InvalidMaxBidsPerIteration();
        uint256 oldValue = maxBidsPerIteration;
        maxBidsPerIteration = _maxBidsPerIteration;
        emit MaxBidsPerIterationUpdated(oldValue, _maxBidsPerIteration);
    }

    /// @notice Set maximum users per page
    /// @param _maxUsersPerPage New maximum users per page
    function setMaxUsersPerPage(uint256 _maxUsersPerPage) external onlyOwner {
        if (
            _maxUsersPerPage == 0 ||
            _maxUsersPerPage > MAX_USERS_PER_PAGE_LIMIT
        ) revert InvalidMaxUsersPerPage();
        uint256 oldValue = maxUsersPerPage;
        maxUsersPerPage = _maxUsersPerPage;
        emit MaxUsersPerPageUpdated(oldValue, _maxUsersPerPage);
    }

    /// @notice Set cache threshold percentage
    /// @param _cacheThreshold New cache threshold (1-100)
    function setCacheThreshold(uint256 _cacheThreshold) external onlyOwner {
        if (_cacheThreshold == 0 || _cacheThreshold > 100)
            revert InvalidCacheThreshold();
        uint256 oldValue = cacheThreshold;
        cacheThreshold = _cacheThreshold;
        emit CacheThresholdUpdated(oldValue, _cacheThreshold);
    }

    /// @notice Set horizon seconds for bid decay calculation
    /// @param _horizonSeconds New horizon seconds
    function setHorizonSeconds(uint256 _horizonSeconds) external onlyOwner {
        if (
            _horizonSeconds == 0 || _horizonSeconds > MAX_HORIZON_SECONDS
        ) revert InvalidHorizonSeconds();
        uint256 oldValue = horizonSeconds;
        horizonSeconds = _horizonSeconds;
        emit HorizonSecondsUpdated(oldValue, _horizonSeconds);
    }

    /// @notice Set bid increment for uniqueness
    /// @param _bidIncrement New bid increment
    function setBidIncrement(uint192 _bidIncrement) external onlyOwner {
        if (_bidIncrement == 0 || _bidIncrement > MAX_BID_INCREMENT)
            revert InvalidBidIncrement();
        uint192 oldValue = bidIncrement;
        bidIncrement = _bidIncrement;
        emit BidIncrementUpdated(oldValue, _bidIncrement);
    }

    /// @notice Set maximum activations per iteration
    /// @param _maxActivationsPerIteration New maximum activations per iteration
    function setMaxActivationsPerIteration(
        uint256 _maxActivationsPerIteration
    ) external onlyOwner {
        if (_maxActivationsPerIteration == 0)
            revert InvalidMaxActivationsPerIteration();
        uint256 oldValue = maxActivationsPerIteration;
        maxActivationsPerIteration = _maxActivationsPerIteration;
        emit MaxActivationsPerIterationUpdated(
            oldValue,
            _maxActivationsPerIteration
        );
    }

    // ------------------------------------------------------------------------
    // Contract externalfunctions (user)
    // ------------------------------------------------------------------------

    function insertContract(
        address _contract,
        uint256 _maxBid,
        bool _biddingEnabled,
        bool _autoActivate,
        uint256 _maxActivationCost
    ) external payable {
        if (_contract == address(0)) revert InvalidAddress(); // TODO allow on only stylus contracts
        if (_maxBid < minMaxBidAmount) revert InvalidBid();
        if (_autoActivate && _maxActivationCost == 0)
            revert InvalidActivationCost();
        // The per-contract cap can't exceed the per-user escrow ceiling, otherwise
        // the runtime balance check in _shouldActivate would never let the
        // activation proceed and the slot of state is dead.
        if (_maxActivationCost > maxUserFunds)
            revert InvalidActivationCost();
        ContractConfig[] storage contracts = userContracts[msg.sender];
        uint256 contractsLength = contracts.length;
        if (contractsLength >= maxContractsPerUser) revert TooManyContracts();

        // Add new contract
        // Check if contract is already in the list
        for (uint256 i = 0; i < contractsLength; i++) {
            if (contracts[i].contractAddress == _contract) {
                revert ContractAlreadyExists();
            }
        }

        if (msg.value > 0) _validateFundAmount(msg.sender, msg.value);

        // Add user to set if this is their first contract
        if (contractsLength == 0) {
            usersWithContracts.add(msg.sender);
        }

        contracts.push(
            ContractConfig({
                contractAddress: _contract,
                biddingEnabled: _biddingEnabled,
                autoActivate: _autoActivate,
                maxBid: _maxBid,
                maxActivationCost: _maxActivationCost
            })
        );
        _updateUserBalance(msg.sender, msg.value);
        emit ContractAdded(msg.sender, _contract, _maxBid);
        emit ContractBiddingEnabledUpdated(
            msg.sender,
            _contract,
            _biddingEnabled
        );
        emit ContractAutoActivateUpdated(msg.sender, _contract, _autoActivate);
        emit ContractMaxActivationCostUpdated(
            msg.sender,
            _contract,
            _maxActivationCost
        );
    }

    function updateContract(
        address _contract,
        uint256 _maxBid,
        bool _biddingEnabled,
        bool _autoActivate,
        uint256 _maxActivationCost
    ) external {
        if (_contract == address(0)) revert InvalidAddress();
        if (_maxBid < minMaxBidAmount) revert InvalidBid();
        if (_autoActivate && _maxActivationCost == 0)
            revert InvalidActivationCost();
        if (_maxActivationCost > maxUserFunds)
            revert InvalidActivationCost();

        ContractConfig[] storage contracts = userContracts[msg.sender];
        uint256 contractsLength = contracts.length;
        for (uint256 i = 0; i < contractsLength; i++) {
            if (contracts[i].contractAddress == _contract) {
                contracts[i].maxBid = _maxBid;
                contracts[i].biddingEnabled = _biddingEnabled;
                contracts[i].autoActivate = _autoActivate;
                contracts[i].maxActivationCost = _maxActivationCost;
                emit ContractUpdated(msg.sender, _contract, _maxBid);
                emit ContractBiddingEnabledUpdated(
                    msg.sender,
                    _contract,
                    _biddingEnabled
                );
                emit ContractAutoActivateUpdated(
                    msg.sender,
                    _contract,
                    _autoActivate
                );
                emit ContractMaxActivationCostUpdated(
                    msg.sender,
                    _contract,
                    _maxActivationCost
                );
                return;
            }
        }
        revert ContractNotFound();
    }

    function removeContract(address _contract) external {
        ContractConfig[] storage contracts = userContracts[msg.sender];
        uint256 contractsLength = contracts.length;
        if (contractsLength == 0) revert ContractNotFound();

        for (uint256 i = 0; i < contractsLength; i++) {
            if (contracts[i].contractAddress == _contract) {
                contracts[i] = contracts[contractsLength - 1];
                contracts.pop();

                // Remove user from set if they have no more contracts
                if (contractsLength == 1) {
                    usersWithContracts.remove(msg.sender);
                }

                emit ContractRemoved(msg.sender, _contract);
                return;
            }
        }

        revert ContractNotFound();
    }

    function removeAllContracts() external {
        ContractConfig[] storage contracts = userContracts[msg.sender];
        uint256 length = contracts.length;
        if (length == 0) revert ContractNotFound();

        for (uint256 i = 0; i < length; i++) {
            emit ContractRemoved(msg.sender, contracts[i].contractAddress);
        }
        delete userContracts[msg.sender];

        // Remove user from set since they have no more contracts
        usersWithContracts.remove(msg.sender);
    }

    function getUserContracts()
        external
        view
        returns (ContractConfig[] memory)
    {
        return userContracts[msg.sender];
    }

    function fundBalance() external payable {
        _validateFundAmount(msg.sender, msg.value);
        _updateUserBalance(msg.sender, msg.value);
    }

    function withdrawBalance() external nonReentrant {
        uint256 amount = escrow.depositsOf(msg.sender);
        if (amount == 0) revert InsufficientBalance();

        emit BalanceUpdated(msg.sender, 0);

        escrow.withdraw(payable(msg.sender));
    }

    function getUserBalance() external view returns (uint256) {
        return escrow.depositsOf(msg.sender);
    }

    /// @notice Only accept ETH from the three trusted protocol contracts the
    /// activation/bidding flows rely on: the BiddingEscrow (forwards user
    /// deposits to this contract via withdrawForAutomation), the ArbWasm precompile
    /// (refunds excess msg.value after activateProgram), and the CacheManager
    /// (if it ever refunds after a placeBid). Stranded donations from any
    /// other source are rejected so they can't pollute the balance-delta
    /// refund accounting in _doActivation.
    receive() external payable {
        if (
            msg.sender != address(escrow) &&
            msg.sender != address(arbWasm) &&
            msg.sender != address(cacheManager)
        ) revert UnauthorizedSender();
    }

    // ------------------------------------------------------------------------
    // Contract external functions (operator)
    // ------------------------------------------------------------------------
    // Anyone can call this functions but the operator (owner) should be the only interested party on calling them

    function placeBids(BidRequest[] calldata _bidRequests) external {
        if (_bidRequests.length > maxBidsPerIteration) revert TooManyBids();
        if (_bidRequests.length == 0) return;

        uint256 currentBlock = ARB_SYS.arbBlockNumber();

        for (uint256 i = 0; i < _bidRequests.length; i++) {
            bytes32 codehash = _bidRequests[i].contractAddress.codehash;
            if (
                codehash != bytes32(0) &&
                lastPaidBidBlock[_bidRequests[i].user][codehash] == currentBlock
            ) continue;
            BidResult memory result = _shouldBid(_bidRequests[i], i);
            if (!result.shouldBid) continue;
            bool placed = _placeBid(
                _bidRequests[i].user,
                result.contractConfig,
                result.bidAmount
            );
            if (placed && result.bidAmount != 0 && codehash != bytes32(0)) {
                lastPaidBidBlock[_bidRequests[i].user][codehash] = currentBlock;
            }
        }
    }

    function placeActivations(
        ActivationRequest[] calldata _activationRequests
    ) external nonReentrant {
        if (_activationRequests.length > maxActivationsPerIteration)
            revert TooManyActivations();
        for (uint256 i = 0; i < _activationRequests.length; i++) {
            ActivationResult memory result = _shouldActivate(
                _activationRequests[i]
            );
            if (!result.shouldActivate) continue;
            // Caller has no agency over the value: the contract spends up to
            // the user's per-contract cap. Mirrors how placeBids derives the
            // bid amount internally (BidRequest carries no amount field).
            _activate(
                _activationRequests[i].user,
                result.contractConfig,
                result.contractConfig.maxActivationCost
            );
        }
    }

    // May revert if too many. Better use paginated version.
    function getContracts()
        external
        view
        returns (UserContractsData[] memory allUserContracts)
    {
        uint256 userCount = usersWithContracts.length();
        allUserContracts = new UserContractsData[](userCount);

        for (uint256 i = 0; i < userCount; i++) {
            address user = usersWithContracts.at(i);
            allUserContracts[i] = UserContractsData({
                user: user,
                contracts: userContracts[user]
            });
        }
    }

    /// @notice Get contracts with pagination support
    /// @param offset Starting index for pagination
    /// @param limit Maximum number of users to return (0 = no limit, but capped at 100)
    /// @return userData Array of user contract data
    /// @return hasMore Whether there are more users beyond this page
    function getContractsPaginated(
        uint256 offset,
        uint256 limit
    )
        external
        view
        returns (UserContractsData[] memory userData, bool hasMore)
    {
        uint256 userCount = usersWithContracts.length();

        // Validate offset
        if (offset >= userCount) {
            return (new UserContractsData[](0), false);
        }

        // Cap limit to prevent abuse (max 100 users per call)
        uint256 maxLimit = maxUsersPerPage;
        if (limit == 0 || limit > maxLimit) {
            limit = maxLimit;
        }

        // Calculate actual number of users to return
        uint256 remainingUsers = userCount - offset;
        uint256 usersToReturn = remainingUsers < limit ? remainingUsers : limit;

        // Create result array
        userData = new UserContractsData[](usersToReturn);

        // Populate data
        for (uint256 i = 0; i < usersToReturn; i++) {
            address user = usersWithContracts.at(offset + i);
            userData[i] = UserContractsData({
                user: user,
                contracts: userContracts[user]
            });
        }

        // Check if there are more users
        hasMore = offset + usersToReturn < userCount;
    }

    /// @notice Get total number of users with contracts
    /// @return Total number of users
    function getTotalUsersCount() external view returns (uint256) {
        return usersWithContracts.length();
    }

    /// @notice Get user at specific index (for iteration purposes)
    /// @param index Index of the user
    /// @return User address at the given index
    function getUserAtIndex(uint256 index) external view returns (address) {
        if (index >= usersWithContracts.length()) revert IndexOutOfBounds();
        return usersWithContracts.at(index);
    }

    // ------------------------------------------------------------------------
    // Contract internal functions
    // ------------------------------------------------------------------------

    /// @dev Calculate bid amount using simplified decay-aware logic
    /// @param userMaxBid User's maximum willing bid amount
    /// @param bidIndex Index for uniqueness
    /// @param minBid Minimum bid amount
    /// @return calculatedBid The amount to bid
    function _calculateBidAmount(
        uint256 userMaxBid,
        uint256 bidIndex,
        uint192 minBid
    ) internal view returns (uint192 calculatedBid) {
        // Get cache utilization
        uint256 cacheUtilization = 0;
        try cacheManager.cacheSize() returns (uint64 capacity) {
            try cacheManager.queueSize() returns (uint64 currentSize) {
                if (capacity > 0) {
                    cacheUtilization =
                        (uint256(currentSize) * 100) /
                        uint256(capacity);
                }
            } catch {}
        } catch {}

        // CACHE NOT FULL CASE
        // If cache is not full, return 0.

        // Why not minBid + increment?
        // To avoid CMA users to compete with each other in a loop when cache is not full.
        // The threshold should be set so that the maxSizeContract can fit in the free space, if that condition is true, then minBid will be 0.
        // Otherwise, minBid will be != 0 but we will still bid 0 to make the bid fail and avoid competition.
        // A threshold of 98% for a 512mb Cache means that there is 10mb free space, enough to hold any contract.

        if (cacheUtilization < cacheThreshold) {
            return 0;
        }

        // CACHE FULL CASE (>98% usage)
        // We make the user spend the minimum between:
        // 1. The required bid so that the cache decays to minBid in "horizonSeconds"
        // 2. The user's maxBid

        // Calculate decay value: minBid + decayRate * horizonSeconds
        uint64 decayRate = 0;
        try cacheManager.decay() returns (uint64 rate) {
            decayRate = rate;
        } catch {
            decayRate = 0;
        }

        // Bid index * BID_INCREMENT is used to make the bid unique for all the contract bids in current block.

        uint256 decayValue = uint256(minBid) +
            (uint256(decayRate) * horizonSeconds) +
            bidIndex *
            bidIncrement;

        uint256 bidValue = decayValue < userMaxBid ? decayValue : userMaxBid;

        if (bidValue > type(uint192).max) return type(uint192).max;
        return uint192(bidValue);
    }

    /// @notice Internal function to check if a contract needs bidding
    function _shouldBid(
        BidRequest calldata bidRequest,
        uint256 bidIndex
    ) internal view returns (BidResult memory) {
        address user = bidRequest.user;
        address contractAddress = bidRequest.contractAddress;

        // Negative cases returns false for skipping the bid
        // These are double checks just in case. Off-chain backend should send
        // only valid bids.

        // Are addresses valid?
        if (user == address(0) || contractAddress == address(0))
            return
                BidResult(
                    false,
                    ContractConfig({
                        contractAddress: address(0),
                        biddingEnabled: false,
                        autoActivate: false,
                        maxBid: 0,
                        maxActivationCost: 0
                    }),
                    0
                );

        // Is automated bidding enabled and does the contract belong to user?
        ContractConfig[] storage contracts = userContracts[user];
        uint256 contractsLength = contracts.length;
        for (uint256 j = 0; j < contractsLength; j++) {
            if (contracts[j].contractAddress == contractAddress) {
                // Is automated bidding enabled?
                if (!contracts[j].biddingEnabled)
                    return BidResult(false, contracts[j], 0);

                // Only registered contracts with bidding enabled need the
                // comparatively expensive cache precompile check.
                if (arbWasmCache.codehashIsCached(contractAddress.codehash))
                    return BidResult(
                        false,
                        ContractConfig({
                            contractAddress: address(0),
                            biddingEnabled: false,
                            autoActivate: false,
                            maxBid: 0,
                            maxActivationCost: 0
                        }),
                        0
                    );

                // Calculate bid amount
                uint192 minBid;
                try cacheManager.getMinBid(contractAddress) returns (
                    uint192 value
                ) {
                    minBid = value;
                } catch {
                    return BidResult(false, contracts[j], 0);
                }
                uint192 calculatedBid = _calculateBidAmount(
                    contracts[j].maxBid,
                    bidIndex,
                    minBid
                );

                // Check if bid is valid
                if (calculatedBid < minBid)
                    return BidResult(false, contracts[j], 0);

                // Check balance only if bidding > 0
                if (calculatedBid > 0) {
                    uint256 userBalance = escrow.depositsOf(user);
                    if (calculatedBid > userBalance)
                        return BidResult(false, contracts[j], 0);
                }

                return BidResult(true, contracts[j], calculatedBid);
            }
        }
        // Contract not found.
        return
            BidResult(
                false,
                ContractConfig({
                    contractAddress: address(0),
                    biddingEnabled: false,
                    autoActivate: false,
                    maxBid: 0,
                    maxActivationCost: 0
                }),
                0
            );
    }

    function _placeBid(
        address user,
        ContractConfig memory contractConfig,
        uint192 bidAmount
    ) internal returns (bool placed) {
        address contractAddress = contractConfig.contractAddress;
        uint256 maxBid = contractConfig.maxBid;

        if (bidAmount == 0) {
            // Free bid - place directly without escrow withdrawal
            try cacheManager.placeBid{value: 0}(contractAddress) {
                uint256 userBalance = escrow.depositsOf(user);
                emit BidPlaced(user, contractAddress, 0, maxBid, userBalance);
                return true;
            } catch {
                emit BidError(
                    user,
                    contractAddress,
                    0,
                    'Free bid placement failed'
                );
                return false;
            }
        } else {
            // Paid bid - withdraw from escrow and place bid
            try escrow.withdrawForAutomation(payable(user), bidAmount) {
                try cacheManager.placeBid{value: bidAmount}(contractAddress) {
                    uint256 userBalance = escrow.depositsOf(user);
                    emit BidPlaced(
                        user,
                        contractAddress,
                        bidAmount,
                        maxBid,
                        userBalance
                    );
                    return true;
                } catch {
                    // Return bid amount to user if bid placement fails
                    escrow.deposit{value: bidAmount}(user);
                    emit BidError(
                        user,
                        contractAddress,
                        bidAmount,
                        'Bid placement failed'
                    );
                    return false;
                }
            } catch {
                emit BidError(
                    user,
                    contractAddress,
                    bidAmount,
                    'Insufficient balance'
                );
                return false;
            }
        }
    }

    function _validateFundAmount(address user, uint256 amount) internal view {
        if (amount < minFundAmount) revert InvalidFundAmount();

        uint256 currentBalance = escrow.depositsOf(user);
        if (currentBalance + amount > maxUserFunds)
            revert ExceedsMaxUserFunds();
    }

    /// @notice Updates user balance and emits event
    function _updateUserBalance(address user, uint256 amount) internal {
        escrow.deposit{value: amount}(user);
        emit BalanceUpdated(user, escrow.depositsOf(user));
    }

    /// @notice Internal function to validate an activation request before executing it.
    /// @dev Mirrors the defensive style of _shouldBid: the caller only nominates
    ///      a user/contract pair; the contract decides whether to activate and
    ///      how much to spend (always exactly cfg.maxActivationCost, mirroring
    ///      how _shouldBid derives the bid amount internally from cfg.maxBid).
    function _shouldActivate(
        ActivationRequest calldata request
    ) internal view returns (ActivationResult memory) {
        address user = request.user;
        address contractAddress = request.contractAddress;
        ContractConfig memory empty = ContractConfig({
            contractAddress: address(0),
            biddingEnabled: false,
            autoActivate: false,
            maxBid: 0,
            maxActivationCost: 0
        });

        // Defensive: skip invalid addresses.
        if (user == address(0) || contractAddress == address(0))
            return ActivationResult(false, empty);

        // Cheap checks first so an attacker can't grief operators with batches
        // of unregistered (user, contract) pairs that each cost a precompile
        // read. Locate the user's contract config; bail before touching the
        // precompile if registration/cap/balance invariants don't hold.
        ContractConfig memory cfg;
        bool found;
        ContractConfig[] storage contracts = userContracts[user];
        uint256 contractsLength = contracts.length;
        for (uint256 j = 0; j < contractsLength; j++) {
            if (contracts[j].contractAddress == contractAddress) {
                cfg = contracts[j];
                found = true;
                break;
            }
        }
        if (!found) return ActivationResult(false, empty);
        if (!cfg.autoActivate) return ActivationResult(false, cfg);
        if (cfg.maxActivationCost > escrow.depositsOf(user))
            return ActivationResult(false, cfg);

        // Now check expiry. ArbWasm encodes "expired" two ways depending on
        // Nitro version:
        //   - Old: programTimeLeft returns 0.
        //   - New: programTimeLeft reverts with ProgramExpired(uint64).
        // ProgramNeedsUpgrade also proceeds; never-activated/unknown errors skip.
        try arbWasm.programTimeLeft(contractAddress) returns (uint64 timeLeft) {
            if (timeLeft != 0) return ActivationResult(false, cfg);
        } catch (bytes memory revertData) {
            bytes4 sel;
            if (revertData.length >= 4) {
                assembly {
                    sel := mload(add(revertData, 32))
                }
            }
            if (
                sel != PROGRAM_EXPIRED_SELECTOR &&
                sel != PROGRAM_NEEDS_UPGRADE_SELECTOR
            )
                return ActivationResult(false, cfg);
        }

        return ActivationResult(true, cfg);
    }

    /// @notice Internal function to execute the activation: pulls value from escrow,
    ///         calls activateProgram, and refunds whatever wasn't actually consumed
    ///         based on a balance-delta measurement.
    function _activate(
        address user,
        ContractConfig memory cfg,
        uint256 value
    ) internal {
        // Pull value from user's escrow into this contract.
        try escrow.withdrawForAutomation(payable(user), value) {
            _doActivation(user, cfg.contractAddress, value);
        } catch {
            emit ActivationError(
                user,
                cfg.contractAddress,
                value,
                'Insufficient balance'
            );
        }
    }

    /// @dev Performs the actual activateProgram call once the value has been
    ///      withdrawn from the user's escrow. Uses a balance-delta measurement
    ///      to support either precompile behavior (auto-refund or keep-all).
    function _doActivation(
        address user,
        address contractAddress,
        uint256 value
    ) internal {
        uint256 balanceBefore = address(this).balance;
        try arbWasm.activateProgram{value: value}(contractAddress) returns (
            uint16 version,
            uint256 dataFee
        ) {
            uint256 spent = balanceBefore > address(this).balance
                ? balanceBefore - address(this).balance
                : 0;
            uint256 refund = value > spent ? value - spent : 0;
            if (refund > 0) {
                escrow.deposit{value: refund}(user);
            }
            emit ActivationPerformed(
                user,
                contractAddress,
                version,
                dataFee,
                spent,
                refund,
                escrow.depositsOf(user)
            );
        } catch (bytes memory revertData) {
            // Activation reverted: the EVM returns the value to msg.sender
            // (this contract), so we can re-deposit the full amount. We also
            // surface the raw revert payload so operators can decode the
            // specific ArbWasm custom error.
            escrow.deposit{value: value}(user);
            emit ActivationError(
                user,
                contractAddress,
                value,
                'Activation failed'
            );
            emit ActivationRevertData(user, contractAddress, revertData);
        }
    }
}

